import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matmul_cute(torch::Tensor A, torch::Tensor B);
"""

matmul_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>
#include <algorithm>

#include <cute/tensor.hpp>

using namespace cute;

// Split-K tiled GEMM: C(M,N) += A(M,K) * B(K,N)
// A is (M,K) row-major, B is (K,N) row-major, C is (M,N) row-major.
// Each CTA computes a partial (BM x BN) tile over a contiguous chunk of K
// and atomically accumulates it into C (C is zero-initialized by the caller).
template <typename T>
__global__ static void
gemm_splitk_kernel(const T* __restrict__ A,
                   const T* __restrict__ B,
                   T* __restrict__ C,
                   int M, int N, int K,
                   int k_tiles_per_split)
{
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 32;

  // Full tensors. mB is viewed as (N,K) so both operands reduce over mode-1.
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));   // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, N));   // (N,K)
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));   // (M,N)

  // CTA tiles
  auto cta_tiler = make_shape(Int<BM>{}, Int<BN>{}, Int<BK>{});
  auto cta_coord = make_coord((int)blockIdx.x, (int)blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X,_1>{});   // (BM,BK,kt)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step< X,_1,_1>{});   // (BN,BK,kt)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1, X>{});   // (BM,BN)

  // Shared memory (sA K-major and sB N-major for conflict-free smem stores)
  __shared__ T smemA[BM*BK];
  __shared__ T smemB[BN*BK];
  Tensor sA = make_tensor(make_smem_ptr(smemA),
                          make_layout(make_shape(Int<BM>{}, Int<BK>{}),
                                      make_stride(Int<BK>{}, Int<1>{})));
  Tensor sB = make_tensor(make_smem_ptr(smemB),
                          make_layout(make_shape(Int<BN>{}, Int<BK>{}),
                                      make_stride(Int<1>{}, Int<BN>{})));

  // Thread layouts (256 threads).
  // tA: consecutive threads sweep K (stride-1 in gmem A) -> coalesced loads.
  auto tA = make_layout(make_shape(Int<8>{}, Int<32>{}), make_stride(Int<32>{}, Int<1>{}));
  // tB: consecutive threads sweep N (stride-1 in gmem B) -> coalesced loads.
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  // tC: 16x16 threads over the (BM,BN) tile -> 8x8 accumulators per thread.
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  const int tid = (int)threadIdx.x;

  Tensor tAgA = local_partition(gA, tA, tid);   // (16,1,kt)
  Tensor tAsA = local_partition(sA, tA, tid);   // (16,1)
  Tensor tBgB = local_partition(gB, tB, tid);   // (4,4,kt)
  Tensor tBsB = local_partition(sB, tB, tid);   // (4,4)

  Tensor tCsA = local_partition(sA, tC, tid, Step<_1, X>{});  // (8,BK)
  Tensor tCsB = local_partition(sB, tC, tid, Step< X,_1>{});  // (8,BK)
  Tensor tCgC = local_partition(gC, tC, tid, Step<_1,_1>{});  // (8,8)

  Tensor tCrC = make_tensor_like(tCgC);   // (8,8) register accumulators
  clear(tCrC);

  // Register fragments for gmem prefetch (double buffering through registers)
  Tensor tArA = make_tensor_like(tAsA);   // (16,1)
  Tensor tBrB = make_tensor_like(tBsB);   // (4,4)

  const int k_tiles_total = size<2>(tAgA);
  const int k_begin = (int)blockIdx.z * k_tiles_per_split;
  int k_end = k_begin + k_tiles_per_split;
  if (k_end > k_tiles_total) k_end = k_tiles_total;

  if (k_begin < k_end) {
    // Prologue: prefetch first k-tile of this split into registers
    copy(tAgA(_,_,k_begin), tArA);
    copy(tBgB(_,_,k_begin), tBrB);

    for (int kt = k_begin; kt < k_end; ++kt) {
      // Stage prefetched tile into shared memory
      copy(tArA, tAsA);
      copy(tBrB, tBsB);
      __syncthreads();

      // Prefetch next k-tile into registers (overlaps with compute below)
      if (kt + 1 < k_end) {
        copy(tAgA(_,_,kt+1), tArA);
        copy(tBgB(_,_,kt+1), tBrB);
      }

      // C += A * B on the smem tile
      gemm(tCsA, tCsB, tCrC);
      __syncthreads();
    }

    // Split-K reduction: accumulate partial tile into C
    CUTE_UNROLL
    for (int i = 0; i < size(tCrC); ++i) {
      atomicAdd(&tCgC(i), tCrC(i));
    }
  }
}

torch::Tensor matmul_cute(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  const int64_t M = A.size(0);
  const int64_t K = A.size(1);
  const int64_t N = B.size(1);
  TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");

  constexpr int BM = 128, BN = 128, BK = 32;
  TORCH_CHECK(M % BM == 0 && N % BN == 0 && K % BK == 0,
              "Require M, N divisible by 128 and K divisible by 32");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::zeros({M, N}, A.options());

  const int k_tiles_total = (int)(K / BK);
  const int tiles = (int)((M / BM) * (N / BN));

  // Pick the K split so that the grid fills the device.
  int sm_count = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
  int target_blocks = 4 * sm_count;
  int splits = target_blocks / tiles;
  if (splits < 1) splits = 1;
  if (splits > k_tiles_total) splits = k_tiles_total;
  int k_tiles_per_split = (k_tiles_total + splits - 1) / splits;

  dim3 grid((unsigned)(M / BM), (unsigned)(N / BN), (unsigned)splits);
  dim3 block(256);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_splitk_kernel<float><<<grid, block, 0, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      (int)M, (int)N, (int)K,
      k_tiles_per_split);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE split-K GEMM launch failed: ",
              cudaGetErrorString(err));
  return C;
}
"""

matmul_ext = load_inline(
    name="cute_splitk_gemm_ext",
    cpp_sources=matmul_cpp_decl,
    cuda_sources=matmul_cuda_src,
    functions=["matmul_cute"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    C = A * B for A:(M,K), B:(K,N) with very large K, implemented with a
    single custom CuTe CUDA kernel: a tiled 128x128x32 GEMM with split-K
    across the huge reduction dimension, register-prefetch double buffering,
    and an atomic-accumulate epilogue into a zero-initialized C.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matmul_cute(A, B)

